use axum::http::HeaderValue;
use axum::http::header::HeaderName;
use axum::middleware::Next;
use axum::response::Response;
use uuid::Uuid;

/// The response (and request) header carrying the request tracking identifier.
static X_REQUEST_ID: HeaderName = HeaderName::from_static("x-request-id");

/// Attach an `x-request-id` header to each HTTP response.
///
/// When the incoming request already carries an `X-Request-Id` header, its
/// value is echoed back unchanged. Otherwise a fresh UUID v4, formatted as 32
/// ASCII hex digits, is generated.
///
/// Mirrors the Python frontend's `XRequestIdMiddleware`.
pub async fn set_request_id(req: Request, next: Next) -> Response {
    let request_id = req
        .headers()
        .get(&X_REQUEST_ID)
        .cloned()
        .unwrap_or_else(|| {
            HeaderValue::from_str(&Uuid::new_v4().simple().to_string())
                .expect("uuid hex is always a valid header value")
        });

    let mut response = next.run(req).await;
    response.headers_mut().insert(&X_REQUEST_ID, request_id);
    response
}
